 function validateWeights(item){if(item.workflow&&!(item.workflow.legacyClosed||item.workflow.legacyPending)){if(!item.team.length)return '请至少选择一位团队成员';if(item.team.some(m=>!m.inactive&&!m.role?.trim()))return '请填写每位成员的分工';return ''}if(!item.team.length)return '请至少选择一位团队成员';const ids=new Set(item.team.map(m=>m.personId));if(item.team.some(m=>!m.role.trim()))return '请填写每位成员的分工';if(!item.tasks.length||Math.abs(item.tasks.reduce((s,t)=>s+Number(t.weight),0)-100)>0.001)return '任务权重合计必须为 100%';for(const t of item.tasks){if(!t.name.trim()||!Number.isFinite(Number(t.weight))||t.weight<0)return '请填写有效任务名称及非负权重';const entries=Object.entries(t.allocations);if(entries.some(([id,p])=>!ids.has(id)||!Number.isFinite(Number(p))||p<0||p>100))return '任务成员比例必须在 0–100% 之间';if(Math.abs(entries.reduce((s,[,p])=>s+Number(p),0)-100)>0.001)return '每项任务的成员分配合计必须为 100%'}return ''}
